package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
class ScviModelMetadataTest {
    @TempDir Path root;private int serial;
    private static final ScviModelMetadata.Limits LIMITS=ScviModelMetadata.Limits.standard();
    private static final ScviModelMetadata.Expected EXPECTED=ScviModelMetadata.Expected.query();
    private record Fixture(ScviModelBytes.Prepared model,Path directory,Map<String,Object> data) { }
    private static Map<String,Object> scalar(String kind,String value){return new LinkedHashMap<>(Map.of("kind",kind,"value",value));}
    private static Map<String,Object> mapping(Map<String,Object> entries){return new LinkedHashMap<>(Map.of("kind","mapping","entries",entries));}
    private static String sha(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}
    private Fixture fixture(String dtype)throws Exception{
        Path source=root.resolve("source-"+serial++);Files.write(source,new byte[]{1,2,3,4});var review=new ScviModelBytes.Review("test","self-created opaque byte fixture;not deserialized","component-only metadata tests",ScviText.hash(source,4096,()->{}),true);var model=ScviModelBytes.prepare(source,review,ScviModelRequest.Release.V1_3_0,ScviModelRequest.Family.SCANVI,root.resolve("prepared-"+serial++),ScviModelBytes.Limits.standard(),()->{});
        Path dir=Files.createDirectory(root.resolve("metadata-"+serial++));var data=new LinkedHashMap<String,Object>();data.put("status","completed-original-model-metadata-inspection-only");data.put("model_analysis_completed",false);data.put("source_sha256",review.expectedSha256());data.put("saved_release","1.3.0");data.put("family","SCANVI");data.put("trained",true);data.put("genes",new ArrayList<>(List.of("g0","g1")));data.put("registered_genes",new ArrayList<>(List.of("g0","g1")));data.put("registered_n_vars",2);data.put("registered_n_cells",3);data.put("input_data_registry",new LinkedHashMap<>(Map.of("attr_name","layers","attr_key","counts")));
        var setup=new LinkedHashMap<String,Object>();setup.put("batch_key","batch");setup.put("labels_key","label");setup.put("layer","counts");setup.put("categorical_covariate_keys",null);setup.put("continuous_covariate_keys",null);setup.put("extra",new LinkedHashMap<>(Map.of("list",new ArrayList<>(List.of(1)))));data.put("setup",setup);
        data.put("batch",new LinkedHashMap<>(Map.of("key","batch","values",List.of(scalar("integer","0"),scalar("integer","1")))));var labels=new ArrayList<>(List.of(scalar("string","0"),scalar("integer","0"),scalar("string","Unlabeled")));data.put("labels",new LinkedHashMap<>(Map.of("key","label","values",labels,"classes",new ArrayList<>(labels.subList(0,2)),"unlabeled",scalar("string","Unlabeled"))));data.put("categorical",List.of());data.put("continuous",List.of());
        var architecture=new LinkedHashMap<String,Object>();architecture.put("n_hidden",2);architecture.put("n_latent",1);architecture.put("n_layers",1);architecture.put("dropout_rate",.1);architecture.put("dispersion","gene");architecture.put("linear_classifier",false);data.put("architecture",architecture);
        String[] keys={"z_encoder.mean_encoder.weight","decoder.px_scale_decoder.0.weight","classifier.classifier.1.weight","px_r"};long[][] shapes={{1,2},{2,2},{2,2},{2}};var descriptors=new ArrayList<Object>();var entries=new LinkedHashMap<String,Object>();var binary=new ByteArrayOutputStream();
        for(int i=0;i<keys.length;i++){int elements=1;var dimensions=new ArrayList<Long>();for(long n:shapes[i]){elements*=Math.toIntExact(n);dimensions.add(n);}int width=dtype.equals("F64")?8:4;ByteBuffer bytes=ByteBuffer.allocate(elements*width).order(ByteOrder.LITTLE_ENDIAN);for(int j=0;j<elements;j++)if(width==8)bytes.putDouble(i+j+1);else bytes.putFloat(i+j+1);byte[] body=bytes.array();var descriptor=new LinkedHashMap<String,Object>();descriptor.put("path",List.of("model_state_dict",keys[i]));descriptor.put("scope","model");descriptor.put("dtype",dtype);descriptor.put("shape",dimensions);descriptor.put("elements",elements);descriptor.put("offset",binary.size());descriptor.put("bytes",body.length);descriptor.put("sha256",sha(body));descriptors.add(descriptor);binary.write(body);entries.put(keys[i],new LinkedHashMap<>(Map.of("kind","tensor","index",i)));}
        entries.put("pyro_param_store",mapping(new LinkedHashMap<>(Map.of("params",mapping(new LinkedHashMap<>()),"constraints",mapping(new LinkedHashMap<>())))));data.put("state_tree",mapping(entries));data.put("tensors",descriptors);data.put("tensor_file_bytes",binary.size());Files.write(dir.resolve("tensors.bin"),binary.toByteArray());var f=new Fixture(model,dir,data);save(f);return f;
    }
    private static void save(Fixture f)throws Exception{Files.writeString(f.directory.resolve("model.json"),ScviJson.json(f.data)+"\n");}
    @SuppressWarnings("unchecked") private static Map<String,Object> map(Object x){return(Map<String,Object>)x;}
    @SuppressWarnings("unchecked") private static List<Object> list(Object x){return(List<Object>)x;}
    private static ScviModelMetadata.Info validate(Fixture f)throws Exception{save(f);return ScviModelMetadata.validate(f.model,EXPECTED,f.directory,LIMITS,()->{});}
    @Test void actualMetadataAndEveryTensorByteAreAdmittedWithoutAnAnalysisClaim()throws Exception{var f=fixture("F32");var info=validate(f);assertEquals(ScviModelRequest.Family.SCANVI,info.family());assertEquals(List.of("g0","g1"),info.genes());assertEquals(4,info.tensors().size());assertEquals(3,info.registeredCells());assertEquals(1,info.latent());info.requireFloat32Profile();info.verify(LIMITS,()->{});}
    @Test void numericAndStringCategoriesRemainDistinctInLearnedOrder()throws Exception{var info=validate(fixture("F32"));assertEquals(new ScviModelMetadata.Scalar("string","0"),info.classes().get(0));assertEquals(new ScviModelMetadata.Scalar("integer","0"),info.classes().get(1));assertNotEquals(info.classes().get(0),info.classes().get(1));assertEquals("integer",info.batches().get(0).kind());}
    @Test void modelGeneOrderMustAgreeWithTheOriginalRegistryAndRequest()throws Exception{var f=fixture("F32");f.data.put("registered_genes",List.of("g1","g0"));assertThrows(IOException.class,()->validate(f));var g=fixture("F32");assertThrows(IOException.class,()->ScviModelMetadata.validate(g.model,new ScviModelMetadata.Expected(true,List.of("g1","g0"),null),g.directory,LIMITS,()->{}));}
    @Test void classOrderCannotBeReplacedBySortingOrDroppingUnlabeled()throws Exception{var f=fixture("F32");map(f.data.get("labels")).put("classes",List.of(scalar("integer","0"),scalar("string","0")));assertThrows(IOException.class,()->validate(f));var g=fixture("F32");map(g.data.get("labels")).put("classes",List.of(scalar("string","0"),scalar("integer","0"),scalar("string","Unlabeled")));assertThrows(IOException.class,()->validate(g));}
    @Test void sourceDeclarationsNeverOverrideActualReleaseFamilyOrTrainingFlag()throws Exception{for(var entry:Map.of("saved_release","1.2.0","family","SCVI","trained",false).entrySet()){var f=fixture("F32");f.data.put(entry.getKey(),entry.getValue());assertThrows(IOException.class,()->validate(f));}}
    @Test void aRehashedNonfiniteLastTensorValueStillFailsIndependentNativeAudit()throws Exception{var f=fixture("F32");Path p=f.directory.resolve("tensors.bin");byte[] bytes=Files.readAllBytes(p);ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).putFloat(bytes.length-4,Float.NaN);Files.write(p,bytes);var d=map(list(f.data.get("tensors")).get(3));int start=((Number)d.get("offset")).intValue();d.put("sha256",sha(Arrays.copyOfRange(bytes,start,bytes.length)));assertThrows(IOException.class,()->validate(f));}
    @Test void fullTensorOffsetsShapesAndNoTrailingBytesAreRequired()throws Exception{var f=fixture("F32");map(list(f.data.get("tensors")).get(1)).put("shape",List.of(1,4));assertThrows(IOException.class,()->validate(f));var g=fixture("F32");Files.write(g.directory.resolve("tensors.bin"),new byte[]{0},StandardOpenOption.APPEND);assertThrows(IOException.class,()->validate(g));}
    @Test void pyroAndOtherLiteralSavedStateCannotBeDiscarded()throws Exception{var f=fixture("F32");map(map(f.data.get("state_tree")).get("entries")).remove("pyro_param_store");assertThrows(IOException.class,()->validate(f));var g=fixture("F32");map(map(g.data.get("state_tree")).get("entries")).put("literal",Map.of("kind","value","value",Map.of("tensor_index",99)));assertDoesNotThrow(()->validate(g));}
    @Test void everyStateTensorReferenceMustBeUniqueAndComplete()throws Exception{var f=fixture("F32");map(map(f.data.get("state_tree")).get("entries")).remove("px_r");assertThrows(IOException.class,()->validate(f));var g=fixture("F32");map(map(g.data.get("state_tree")).get("entries")).put("extra",Map.of("kind","tensor","index",0));assertThrows(IOException.class,()->validate(g));}
    @Test void architectureAndExpressionLayerClaimsAreCrossChecked()throws Exception{var f=fixture("F32");map(f.data.get("architecture")).put("n_latent",2);assertThrows(IOException.class,()->validate(f));var g=fixture("F32");map(g.data.get("setup")).put("layer","other");assertThrows(IOException.class,()->validate(g));}
    @Test void admittedNestedMetadataIsImmutable()throws Exception{var info=validate(fixture("F32"));assertThrows(UnsupportedOperationException.class,()->map(info.setup().get("extra")).put("new",1));assertThrows(UnsupportedOperationException.class,()->list(map(info.setup().get("extra")).get("list")).add(2));}
    @Test void precisionIsReportedAndNeverSilentlyCastToTheCpuProfile()throws Exception{var info=validate(fixture("F64"));assertEquals(Set.of("F64"),info.modelPrecisions());assertThrows(ScviModelMetadata.Unsupported.class,info::requireFloat32Profile);}
    @Test void completeMetadataByteAndPopulationCapacitiesAreEnforced()throws Exception{var f=fixture("F32");var small=new ScviModelMetadata.Limits(1,1,100,100,100000,100000,10000,10000000,LIMITS.process());assertThrows(IOException.class,()->ScviModelMetadata.validate(f.model,EXPECTED,f.directory,small,()->{}));var byteLimit=new ScviModelMetadata.Limits(1,10,100,100,100000,1,10000,10000000,LIMITS.process());assertThrows(IOException.class,()->ScviModelMetadata.validate(f.model,EXPECTED,f.directory,byteLimit,()->{}));}
    @Test void unexpectedMembersAndLaterStateMutationsInvalidateTheMetadata()throws Exception{var f=fixture("F32");Files.createDirectory(f.directory.resolve("extra"));assertThrows(IOException.class,()->validate(f));var g=fixture("F32");var info=validate(g);Files.writeString(g.directory.resolve("model.json"),"{}");assertThrows(IOException.class,()->info.verify(LIMITS,()->{}));}
}
